import { mkdirSync, writeFileSync, readFileSync } from "node:fs"
import { join } from "node:path"
import { compile } from "json-schema-to-typescript"
import {
  PROTOCOL_VERSION,
  loadSchemaFiles,
  MESSAGE_SCHEMAS,
  rootDir,
  schemasDir,
} from "./lib/load-ajv.mjs"

const outDir = join(rootDir, "clients", "typescript")
mkdirSync(outDir, { recursive: true })

const banner = [
  "/* eslint-disable */",
  "/* Generated by scripts/generate-clients.mjs — do not edit by hand. */",
  `/* Protocol version ${PROTOCOL_VERSION} */`,
  "",
].join("\n")

const moduleNames = []
for (const { name, schema } of loadSchemaFiles()) {
  const base = name.replace(/\.json$/, "")
  const ts = await compile(schema, base, {
    bannerComment: "",
    cwd: schemasDir,
    declareExternallyReferenced: true,
    unreachableDefinitions: true,
    additionalProperties: false,
    style: { semi: false, singleQuote: false },
  })
  const cleaned = ts
    .replace(/^\/\*[\s\S]*?\*\/\s*/m, "")
    .trim()
  writeFileSync(join(outDir, `${base}.ts`), `${banner}${cleaned}\n`)
  moduleNames.push(base)
}

const index = [
  banner.trimEnd(),
  `export const PROTOCOL_VERSION = "${PROTOCOL_VERSION}" as const`,
  "",
  `export type ProtocolSchemaId = ${MESSAGE_SCHEMAS.map((n) => `"${n}"`).join(" | ")}`,
  "",
  ...moduleNames.map((base) => {
    const ns = base.charAt(0).toUpperCase() + base.slice(1)
    return `export * as ${ns} from "./${base}.js"`
  }),
  "",
].join("\n")
writeFileSync(join(outDir, "index.ts"), `${index}\n`)

const catalog = {
  protocol_version: PROTOCOL_VERSION,
  dialect: "https://json-schema.org/draft/2020-12/schema",
  schemas: loadSchemaFiles().map((f) => f.name),
  message_schemas: MESSAGE_SCHEMAS,
  clients: ["typescript"],
  semver_policy: "MAJOR for breaking wire changes (REPOS.md)",
  sources: {
    json_schema: "https://json-schema.org/draft/2020-12/schema",
    semver: "https://semver.org/",
  },
}
writeFileSync(
  join(rootDir, "schemas", "catalog.json"),
  `${JSON.stringify(catalog, null, 2)}\n`
)

const pkgPath = join(rootDir, "package.json")
const pkg = JSON.parse(readFileSync(pkgPath, "utf8"))
pkg.version = PROTOCOL_VERSION
writeFileSync(pkgPath, `${JSON.stringify(pkg, null, 2)}\n`)

console.log(
  `GENERATE_OK protocol_version=${PROTOCOL_VERSION} typescript_files=${loadSchemaFiles().length + 1}`
)
